"""Zero-LLM deterministic P5 T1 / P3-H0-W1 evaluator.

This module is deliberately pure: no network, subprocess, RNG, model import,
or Research Memory mutation. Outcome values are obtainable only through a
``LabelGate`` after PIT membership and entry weights have been frozen.
"""
from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
import math
import os
from pathlib import Path
import resource
import time
from typing import Any, Iterable, Mapping, Sequence

import numpy as np


FLOAT = np.float64
VOID_RULES = {
    "I1": "DATASET_HASH_MISMATCH", "I2": "REVISION_HASH_MISMATCH",
    "I3": "PREREG_HASH_MISMATCH", "I4": "EVALUATOR_HASH_MISMATCH",
    "I5": "AUTHORITY_SCOPE_MISMATCH", "I6": "UNEXPECTED_LABEL_ACCESS",
    "I7": "WRONG_CUTOFF", "I8": "WRONG_UNIVERSE_OR_SOURCE_REVISION",
    "I9": "NUMERIC_FAILURE", "I10": "PARTIAL_ABORTED_ATTEMPT",
    "I11": "DATA_CORRUPTION", "I12": "NONDETERMINISM_OR_UNAUTHORIZED_CALL",
}
RESULT_STATES = {
    "TEST_VOIDED", "EVIDENCE_INSUFFICIENT_CURRENT_COHORT",
    "REPLICATION_SUPPORTED", "REPLICATION_FAILED",
}
REJECTION_RULES = {
    "FORMULA_UNDEFINED_ON_FROZEN_INPUTS", "EXACT_ZERO_XS_VARIANCE",
    "DUPLICATE_CANDIDATE_HASH", "DUPLICATE_WEIGHT_PATH",
}
BANNED_IMPORT_ROOTS = {"socket", "requests", "urllib", "httpx", "subprocess",
                       "random", "secrets", "torch", "tensorflow", "openai"}
TAKER_FEE_PER_SIDE = FLOAT("0.0005")


class EvaluationError(RuntimeError):
    pass


class IntegrityVoid(EvaluationError):
    def __init__(self, rule: str, detail: str):
        if rule not in VOID_RULES:
            raise ValueError("only frozen I1-I12 rules are valid")
        super().__init__(f"{rule}:{VOID_RULES[rule]}:{detail}")
        self.rule = rule
        self.detail = detail


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def file_sha256(path: str | os.PathLike[str]) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def enforce_float64(value: Any, field: str) -> np.ndarray:
    arr = np.asarray(value)
    if arr.dtype != np.dtype("float64"):
        raise IntegrityVoid("I9", f"{field} dtype must be float64")
    if not np.isfinite(arr).all():
        raise IntegrityVoid("I9", f"{field} contains non-finite value")
    return arr


def verify_startup_hashes(actual: Mapping[str, str],
                          expected: Mapping[str, str],
                          scope_actual: str, scope_expected: str,
                          cutoff_actual: str, cutoff_expected: str) -> None:
    rule_by_key = {
        "dataset_manifest": "I1", "revision_lineage": "I2", "prereg": "I3",
        "evaluator": "I4", "universe": "I8", "source_revision": "I8",
    }
    for key, wanted in expected.items():
        if actual.get(key) != wanted:
            raise IntegrityVoid(rule_by_key.get(key, "I5"), f"{key} hash mismatch")
    if scope_actual != scope_expected:
        raise IntegrityVoid("I5", "authority scope mismatch")
    if cutoff_actual != cutoff_expected:
        raise IntegrityVoid("I7", "cutoff mismatch")


def previous_fully_closed_bar(bars: Sequence[Mapping[str, Any]],
                              decision_us: int) -> Mapping[str, Any]:
    eligible = [bar for bar in bars if int(bar["close_us"]) <= decision_us - 1000]
    if not eligible:
        raise EvaluationError("no fully closed bar")
    return max(eligible, key=lambda row: int(row["close_us"]))


def log_basis(perp: np.float64, spot: np.float64) -> np.float64:
    if perp <= 0 or spot <= 0 or not np.isfinite(perp) or not np.isfinite(spot):
        raise EvaluationError("FORMULA_UNDEFINED_ON_FROZEN_INPUTS")
    return FLOAT(np.log(perp) - np.log(spot))


def funding_return(position_sign: np.float64, funding_rate: np.float64) -> np.float64:
    return FLOAT(-FLOAT(position_sign) * FLOAT(funding_rate))


def funding_in_open_closed(events: Sequence[Mapping[str, Any]], start_us: int,
                           end_us: int, position_sign: np.float64) -> np.float64:
    values = [funding_return(position_sign, FLOAT(e["funding_rate"]))
              for e in events if start_us < int(e["market_event_time_us"]) <= end_us]
    return FLOAT(np.sum(np.asarray(values, dtype=np.float64), dtype=np.float64))


def return_components(entry_f: np.float64, exit_f: np.float64,
                      entry_s: np.float64, exit_s: np.float64,
                      funding: np.float64) -> dict[str, np.float64]:
    values = enforce_float64(np.array([entry_f, exit_f, entry_s, exit_s, funding],
                                      dtype=np.float64), "return inputs")
    if np.any(values[:4] <= 0):
        raise IntegrityVoid("I9", "nonpositive price")
    spot = FLOAT(np.log(exit_s) - np.log(entry_s))
    term = FLOAT((np.log(exit_f) - np.log(exit_s)) -
                 (np.log(entry_f) - np.log(entry_s)))
    total = FLOAT(np.log(exit_f) - np.log(entry_f) + funding)
    decomposed = FLOAT(spot + term + funding)
    if total != decomposed and abs(float(total - decomposed)) > np.finfo(np.float64).eps * 8:
        raise IntegrityVoid("I9", "TOTAL decomposition identity failed")
    return {"TOTAL": total, "SPOT": spot, "TERM": term, "FUNDING": FLOAT(funding)}


def freeze_quintile_weights(features: Mapping[str, np.float64]) -> dict[str, Any]:
    rows = []
    for symbol, value in features.items():
        value = FLOAT(value)
        if np.isfinite(value):
            rows.append((symbol.encode("utf-8"), symbol, value))
    rows.sort(key=lambda row: (row[2], row[0]))
    n = len(rows)
    if n < 5:
        return {"state": "STRUCTURALLY_UNDEFINED", "n": n, "weights": {}}
    groups: dict[int, list[str]] = {q: [] for q in range(1, 6)}
    for rank, (_, symbol, _) in enumerate(rows, 1):
        q = min(4, math.floor(5 * (rank - 1) / n)) + 1
        groups[q].append(symbol)
    if any(not symbols for symbols in groups.values()):
        return {"state": "STRUCTURALLY_UNDEFINED", "n": n, "weights": {}}
    weights: dict[str, np.float64] = {}
    for symbol in groups[1]:
        weights[symbol] = FLOAT(1.0 / len(groups[1]))
    for symbol in groups[5]:
        weights[symbol] = FLOAT(-1.0 / len(groups[5]))
    frozen = {"state": "FROZEN", "n": n, "groups": groups,
              "weights": weights,
              "weight_path_sha256": digest(canonical_bytes(
                  {k: float(v) for k, v in sorted(weights.items())}))}
    return frozen


@dataclass
class LabelGate:
    """Synthetic/production-neutral structural gate; labels remain private."""
    _labels: Mapping[str, Mapping[str, np.float64]]
    allowed_end_us: int
    _opened: bool = False
    _frozen_weights_hash: str | None = None

    def open(self, frozen: Mapping[str, Any], authority_applied: bool,
             label_end_us: int) -> None:
        if self._opened:
            raise IntegrityVoid("I6", "label gate already opened")
        if not authority_applied:
            raise IntegrityVoid("I5", "authority not APPLIED")
        if frozen.get("state") != "FROZEN" or not frozen.get("weight_path_sha256"):
            raise IntegrityVoid("I6", "weights not frozen before label access")
        if label_end_us > self.allowed_end_us:
            raise IntegrityVoid("I6", "label read beyond permitted development window")
        self._frozen_weights_hash = str(frozen["weight_path_sha256"])
        self._opened = True

    def read(self, symbol: str) -> Mapping[str, np.float64] | None:
        if not self._opened:
            raise IntegrityVoid("I6", "label access before weight freeze")
        return self._labels.get(symbol)


def evaluate_frozen_portfolio(frozen: Mapping[str, Any], gate: LabelGate) -> dict[str, Any]:
    if frozen.get("state") != "FROZEN":
        return {"state": "STRUCTURALLY_UNDEFINED"}
    total = FLOAT(0.0); spot = FLOAT(0.0); term = FLOAT(0.0); funding = FLOAT(0.0)
    missing = 0
    for symbol, weight in frozen["weights"].items():
        row = gate.read(symbol)
        if row is None:
            missing += 1
            continue  # frozen weight is NOT renormalized
        w = FLOAT(weight)
        total = FLOAT(total + w * FLOAT(row["TOTAL"]))
        spot = FLOAT(spot + w * FLOAT(row["SPOT"]))
        term = FLOAT(term + w * FLOAT(row["TERM"]))
        funding = FLOAT(funding + w * FLOAT(row["FUNDING"]))
    return {"state": "OUTCOME_COMPLETE" if missing == 0 else "OUTCOME_INCOMPLETE",
            "TOTAL": total, "SPOT": spot, "TERM": term, "FUNDING": funding,
            "OUTCOME_INCOMPLETE": missing,
            "frozen_weight_path_sha256": frozen["weight_path_sha256"]}


def filtering_first_counterexample(features: Mapping[str, np.float64],
                                   labels: Mapping[str, Any]) -> bool:
    correct = freeze_quintile_weights(features)
    filtered = freeze_quintile_weights({k: v for k, v in features.items() if k in labels})
    return correct.get("weight_path_sha256") != filtered.get("weight_path_sha256")


def hac_lag(estimator_t: int, horizon_hours: int) -> int:
    if estimator_t < 1 or horizon_hours not in (8, 24, 168):
        raise EvaluationError("unsupported HAC inputs")
    plug_in = math.floor(4 * (estimator_t / 100) ** (2 / 9))
    overlap_floor = horizon_hours // 8 - 1
    return max(overlap_floor, plug_in)


def hac_mean(series: np.ndarray, horizon_hours: int) -> dict[str, Any]:
    x = enforce_float64(series, "HAC series")
    t = len(x)
    m = hac_lag(t, horizon_hours)
    centered = x - np.mean(x, dtype=np.float64)
    gamma0 = FLOAT(np.dot(centered, centered) / t)
    lrv = gamma0
    for j in range(1, min(m, t - 1) + 1):
        gamma = FLOAT(np.dot(centered[j:], centered[:-j]) / t)
        lrv = FLOAT(lrv + 2 * (1 - j / (m + 1)) * gamma)
    info1 = t >= m + 2
    info2 = bool(np.isfinite(lrv) and lrv > 0)
    se = FLOAT(np.sqrt(lrv / t)) if info1 and info2 else FLOAT(np.nan)
    mean = FLOAT(np.mean(x, dtype=np.float64))
    construction_t = FLOAT(mean / se) if np.isfinite(se) and se > 0 else FLOAT(np.nan)
    return {"mean": mean, "hac_lag": m, "long_run_variance": lrv,
            "hac_se": se, "construction_t": construction_t,
            "ESTIMATOR_T": t, "INFO_1": info1, "INFO_2": info2,
            "INFO": info1 and info2}


def result_state(integrity_pass: bool, info: bool, estimate: np.float64,
                 two_sided_p: np.float64) -> str:
    if not integrity_pass:
        return "TEST_VOIDED"
    if not info:
        return "EVIDENCE_INSUFFICIENT_CURRENT_COHORT"
    if estimate > 0 and two_sided_p < FLOAT(0.05):
        return "REPLICATION_SUPPORTED"
    return "REPLICATION_FAILED"


def two_sided_normal_p(construction_t: np.float64) -> np.float64:
    if not np.isfinite(construction_t):
        raise IntegrityVoid("I9", "non-finite construction t")
    return FLOAT(math.erfc(abs(float(construction_t)) / math.sqrt(2.0)))


def t1_result_artifact(series: np.ndarray, components: Sequence[Mapping[str, Any]],
                       integrity_pass: bool = True) -> dict[str, Any]:
    stats = hac_mean(series, 8)
    p = two_sided_normal_p(stats["construction_t"]) if stats["INFO"] else None
    state = result_state(integrity_pass, stats["INFO"], stats["mean"],
                         FLOAT(p) if p is not None else FLOAT(1.0))
    complete = [row for row in components if row.get("state") == "OUTCOME_COMPLETE"]
    def mean_field(field: str) -> float | None:
        return (float(np.mean(np.asarray([row[field] for row in complete], dtype=np.float64),
                              dtype=np.float64)) if complete else None)
    return {
        "result_state": state, "gross_mean": float(stats["mean"]),
        "hac_se": None if not np.isfinite(stats["hac_se"]) else float(stats["hac_se"]),
        "construction_t": None if not np.isfinite(stats["construction_t"]) else float(stats["construction_t"]),
        "two_sided_normal_p": p, "ESTIMATOR_T": stats["ESTIMATOR_T"],
        "INFO_1": stats["INFO_1"], "INFO_2": stats["INFO_2"], "INFO": stats["INFO"],
        "spot_component": mean_field("SPOT"), "term_component": mean_field("TERM"),
        "funding_component": mean_field("FUNDING"),
        "OUTCOME_INCOMPLETE": sum(row.get("state") == "OUTCOME_INCOMPLETE" for row in components),
        "STRUCTURALLY_UNDEFINED": sum(row.get("state") == "STRUCTURALLY_UNDEFINED" for row in components),
        "acf_decay": "REPORT_ONLY", "variance_ratio": "REPORT_ONLY",
    }


def fee_only_diagnostic(horizon_hours: int, turnover: np.float64 | None) -> float | str:
    if horizon_hours != 8:
        return "UNAVAILABLE"
    if turnover is None or not np.isfinite(turnover) or turnover < 0:
        raise EvaluationError("8h turnover required for fee-only diagnostic")
    return float(FLOAT(turnover) * TAKER_FEE_PER_SIDE)


def wave1_diagnostic(candidate: Mapping[str, Any], series: np.ndarray,
                     long_leg: np.ndarray, short_leg: np.ndarray,
                     components: Sequence[Mapping[str, Any]], turnover: np.float64 | None,
                     source_alignment_t: np.float64 | None = None) -> dict[str, Any]:
    horizon = int(candidate["holding_horizon_hours"])
    stats = hac_mean(series, horizon)
    for name, values in (("long_leg", long_leg), ("short_leg", short_leg)):
        enforce_float64(values, name)
    complete = [row for row in components if row.get("state") == "OUTCOME_COMPLETE"]
    def component(field: str) -> float | None:
        return float(np.mean(np.asarray([r[field] for r in complete], dtype=np.float64),
                             dtype=np.float64)) if complete else None
    total_count = len(components)
    return {
        "candidate_id": candidate["candidate_id"], "gross_mean": float(stats["mean"]),
        "net_fee_only_mean": fee_only_diagnostic(horizon, turnover),
        "hac_se": None if not np.isfinite(stats["hac_se"]) else float(stats["hac_se"]),
        "construction_t": None if not np.isfinite(stats["construction_t"]) else float(stats["construction_t"]),
        "ESTIMATOR_T": stats["ESTIMATOR_T"], "effective_information_note": "HAC_INFO=" + str(stats["INFO"]),
        "long_leg_mean": float(np.mean(long_leg, dtype=np.float64)),
        "short_leg_mean": float(np.mean(short_leg, dtype=np.float64)),
        "funding_component": component("FUNDING"), "term_component": component("TERM"),
        "spot_component": component("SPOT"), "turnover": None if turnover is None else float(turnover),
        "coverage": (len(complete) / total_count if total_count else 0.0),
        "OUTCOME_INCOMPLETE": sum(r.get("state") == "OUTCOME_INCOMPLETE" for r in components),
        "STRUCTURALLY_UNDEFINED": sum(r.get("state") == "STRUCTURALLY_UNDEFINED" for r in components),
        "SOURCE_ALIGNMENT_T": None if source_alignment_t is None else float(source_alignment_t),
    }


def risc_record(wave_id: str, candidate_list_sha256: str, candidate_count: int,
                attempted: int, completed: int, rejected: Mapping[str, int]) -> dict[str, Any]:
    if candidate_count != 174 or attempted > candidate_count or completed > attempted:
        raise IntegrityVoid("I5", "RISC scope/count mismatch")
    if any(key not in REJECTION_RULES or value < 0 for key, value in rejected.items()):
        raise IntegrityVoid("I5", "RISC rejection rule mismatch")
    record = {"wave_id": wave_id, "candidate_list_sha256": candidate_list_sha256,
              "candidate_count": candidate_count, "attempted": attempted,
              "completed": completed, "rejected": dict(sorted(rejected.items()))}
    record["risc_sha256"] = digest(canonical_bytes(record))
    return record


def rejection_reason(feature_values: np.ndarray, candidate_hash: str,
                     weight_path_sha256: str, seen_candidates: set[str],
                     seen_paths: set[str]) -> str | None:
    x = enforce_float64(feature_values, "candidate feature")
    if len(x) == 0:
        return "FORMULA_UNDEFINED_ON_FROZEN_INPUTS"
    if np.var(x, ddof=0, dtype=np.float64) == FLOAT(0.0):
        return "EXACT_ZERO_XS_VARIANCE"
    if candidate_hash in seen_candidates:
        return "DUPLICATE_CANDIDATE_HASH"
    if weight_path_sha256 in seen_paths:
        return "DUPLICATE_WEIGHT_PATH"
    seen_candidates.add(candidate_hash); seen_paths.add(weight_path_sha256)
    return None


def enforce_i12_source(source_path: str | os.PathLike[str]) -> None:
    import ast
    tree = ast.parse(Path(source_path).read_text(encoding="utf-8"))
    for node in ast.walk(tree):
        roots: list[str] = []
        if isinstance(node, ast.Import): roots = [alias.name.split(".")[0] for alias in node.names]
        elif isinstance(node, ast.ImportFrom) and node.module: roots = [node.module.split(".")[0]]
        if BANNED_IMPORT_ROOTS.intersection(roots):
            raise IntegrityVoid("I12", f"banned import: {sorted(BANNED_IMPORT_ROOTS.intersection(roots))}")


def feature_value(core: str, history: Mapping[str, np.ndarray], lookback_days: int | None) -> np.float64:
    y = enforce_float64(history["basis"], "basis")
    if core == "LB_LEVEL": return FLOAT(y[-1])
    if core == "BASIS_CHANGE_1CYCLE": return FLOAT(y[-1] - y[-2])
    if core == "BASIS_ACCEL_1CYCLE": return FLOAT((y[-1]-y[-2])-(y[-2]-y[-3]))
    if lookback_days is None: raise EvaluationError("lookback required")
    n = 3 * lookback_days
    if core == "BASIS_PERSISTENCE_L":
        z = y[-n:]; return FLOAT(np.mean(np.sign(z) == np.sign(y[-1])))
    if core == "BM_EQ70_L":
        sr=enforce_float64(history["spot_returns"],"spot_returns")[-n:]
        fr=enforce_float64(history["perp_returns"],"perp_returns")[-n:]
        return FLOAT(np.prod(1+sr,dtype=np.float64)-np.prod(1+fr,dtype=np.float64))
    pv=enforce_float64(history["quote_volume"],"quote_volume")[-n:]
    imb=enforce_float64(history["signed_quote_volume"],"signed_quote_volume")[-n:]
    if core == "PV_L":
        m=FLOAT(np.mean(pv,dtype=np.float64));
        if m <= 0: raise EvaluationError("FORMULA_UNDEFINED_ON_FROZEN_INPUTS")
        return FLOAT(np.log(m))
    if core == "PV_VAR_L": return FLOAT(np.var(pv,ddof=0,dtype=np.float64))
    if core == "PV_IMB_L": return FLOAT(np.mean(imb,dtype=np.float64))
    if core == "PV_IMB_VAR_L": return FLOAT(np.var(imb,ddof=0,dtype=np.float64))
    if core == "DAMIHUD_L":
        if np.any(pv == 0): raise EvaluationError("FORMULA_UNDEFINED_ON_FROZEN_INPUTS")
        fr=enforce_float64(history["perp_returns"],"perp_returns")[-n:]
        return FLOAT(np.mean(np.abs(fr)/pv,dtype=np.float64))
    raise EvaluationError("unknown frozen feature core")


def validate_candidate(candidate: Mapping[str, Any], seen_hashes: set[str],
                       seen_weight_paths: set[str]) -> str | None:
    if candidate.get("neutralization") != "NONE":
        raise EvaluationError("EQ71_REFUSED")
    chash=digest(canonical_bytes(candidate))
    if chash in seen_hashes: return "DUPLICATE_CANDIDATE_HASH"
    seen_hashes.add(chash)
    weight_path=candidate.get("weight_path_sha256")
    if weight_path and weight_path in seen_weight_paths: return "DUPLICATE_WEIGHT_PATH"
    if weight_path: seen_weight_paths.add(weight_path)
    return None


def write_checkpoint(path: Path, payload: Mapping[str, Any]) -> str:
    data=canonical_bytes(payload); target=Path(path)
    if target.exists(): raise EvaluationError("checkpoint is write-once")
    target.parent.mkdir(parents=True,exist_ok=True)
    with target.open("xb") as f:
        f.write(data); f.flush(); os.fsync(f.fileno())
    return digest(data)


def read_checkpoint(path: Path, expected_sha256: str) -> dict[str, Any]:
    data=Path(path).read_bytes()
    if digest(data)!=expected_sha256: raise IntegrityVoid("I11","checkpoint corruption")
    obj=json.loads(data)
    if obj.get("state") not in {"ATTEMPT_VOID","TERMINAL"}:
        raise IntegrityVoid("I10","partial aborted attempt")
    return obj


def deterministic_synthetic_panel(n_symbols: int, n_cycles: int) -> dict[str, Any]:
    # Closed arithmetic construction, deliberately no RNG.
    symbols=[f"S{i:04d}" for i in range(n_symbols)]
    cycles=np.arange(n_cycles,dtype=np.float64)[:,None]
    sym=np.arange(n_symbols,dtype=np.float64)[None,:]
    basis=(sym+1)*FLOAT(1e-4)+cycles*FLOAT(1e-7)
    labels=(sym-n_symbols/2)*FLOAT(1e-5)+cycles*FLOAT(1e-8)
    return {"symbols":symbols,"basis":basis.astype(np.float64),
            "labels":labels.astype(np.float64)}


def synthetic_full_path(candidate_list: Mapping[str, Any], n_symbols: int=156,
                        n_cycles: int=2700, checkpoint_dir: Path|None=None) -> dict[str, Any]:
    started=time.perf_counter(); marks={}
    startup=time.perf_counter()-started
    manifest_start=time.perf_counter(); canonical_bytes(candidate_list); marks["MANIFEST_IO_WALL_SECONDS"]=time.perf_counter()-manifest_start
    feature_start=time.perf_counter(); panel=deterministic_synthetic_panel(n_symbols,n_cycles); marks["FEATURE_BUILD_WALL_SECONDS"]=time.perf_counter()-feature_start
    loop_start=time.perf_counter(); diagnostics=[]
    for idx,candidate in enumerate(candidate_list["candidates"]):
        values=panel["basis"][-1] * FLOAT(1+idx*1e-6)
        frozen=freeze_quintile_weights(dict(zip(panel["symbols"],values,strict=True)))
        series=(np.mean(panel["labels"][:,-max(1,n_symbols//5):],axis=1,dtype=np.float64)-
                np.mean(panel["labels"][:,:max(1,n_symbols//5)],axis=1,dtype=np.float64))
        h=hac_mean(series.astype(np.float64),int(candidate["holding_horizon_hours"]))
        diagnostics.append({"candidate_id":candidate["candidate_id"],"weight_path_sha256":frozen["weight_path_sha256"],"hac_lag":h["hac_lag"],"ESTIMATOR_T":h["ESTIMATOR_T"]})
    marks["CANDIDATE_LOOP_WALL_SECONDS"]=time.perf_counter()-loop_start
    marks["HAC_WALL_SECONDS"]=marks["CANDIDATE_LOOP_WALL_SECONDS"]
    ser_start=time.perf_counter(); out={"candidate_count":len(diagnostics),"diagnostics":diagnostics}; final=canonical_bytes(out); marks["SERIALIZATION_WALL_SECONDS"]=time.perf_counter()-ser_start
    marks["CHECKPOINT_WALL_SECONDS"]=0.0; marks["RESUME_WALL_SECONDS"]=0.0
    if checkpoint_dir is not None:
        cp_start=time.perf_counter(); cp=Path(checkpoint_dir)/"attempt_void.json"; cp_hash=write_checkpoint(cp,{"state":"ATTEMPT_VOID","logical_trial_id":"synthetic-logical-1","next_index":87}); marks["CHECKPOINT_WALL_SECONDS"]=time.perf_counter()-cp_start
        resume=time.perf_counter(); read_checkpoint(cp,cp_hash); marks["RESUME_WALL_SECONDS"]=time.perf_counter()-resume
    marks["STARTUP_WALL_SECONDS"]=startup
    marks["TOTAL_WALL_SECONDS"]=time.perf_counter()-started
    marks["PEAK_RSS_BYTES"]=int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024)
    marks["CANDIDATES_PER_SECOND"]=len(diagnostics)/marks["TOTAL_WALL_SECONDS"]
    marks["canonical_output_sha256"]=digest(final)
    marks["candidate_count"]=len(diagnostics)
    return marks

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}

RESOURCE_POLICY_TYPE = "WAVE1_CUMULATIVE_ACTIVE_WALL_TIME_V1"
RESOURCE_POLICY_KEYS = {
    "policy_type", "wall_time_expiry_seconds", "clock", "starts_at",
    "accumulation", "checkpoint_semantics", "on_exhaustion",
    "scientific_early_stop", "candidate_count", "decision_basis",
}
RESOURCE_DECISION_BASIS_KEYS = {
    "source", "benchmark_sha256", "real_p5_labels_read_before_choice",
}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


def validate_resource_policy(value: Any) -> dict[str, Any]:
    """Validate the owner-late-bound, outcome-blind Wave-1 resource policy.

    Amendment D defines ``wall_time_expiry`` as a cumulative active-attempt
    duration in integer seconds.  It is deliberately distinct from the
    security credential's absolute ``expires_at`` timestamp.  The owner
    chooses the integer after the sealed synthetic benchmark and before the
    first P3 real-label access; this function never supplies a default.
    """
    if not isinstance(value, dict) or set(value) != RESOURCE_POLICY_KEYS:
        raise AuthorityError("RESOURCE_POLICY_EXACT_FIELDS_REQUIRED")
    if value["policy_type"] != RESOURCE_POLICY_TYPE:
        raise AuthorityError("RESOURCE_POLICY_TYPE_INVALID")
    seconds = value["wall_time_expiry_seconds"]
    if isinstance(seconds, bool) or not isinstance(seconds, int) or seconds <= 0:
        raise AuthorityError("RESOURCE_POLICY_SECONDS_INVALID")
    expected = {
        "clock": "DAEMON_MONOTONIC_ACTIVE_ATTEMPT_TIME",
        "starts_at": "WAVE1_APPLIED",
        "accumulation": "SUM_ALL_ATTEMPTS_SAME_LOGICAL_WAVE",
        "checkpoint_semantics": "SEALED_PARTIAL_CHECKPOINT_RESUME_ONLY",
        "on_exhaustion": "RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED",
        "scientific_early_stop": False,
        "candidate_count": 174,
    }
    if any(value.get(key) != wanted for key, wanted in expected.items()):
        raise AuthorityError("RESOURCE_POLICY_SEMANTICS_INVALID")
    basis = value.get("decision_basis")
    if not isinstance(basis, dict) or set(basis) != RESOURCE_DECISION_BASIS_KEYS:
        raise AuthorityError("RESOURCE_POLICY_DECISION_BASIS_INVALID")
    if basis.get("source") != "SEALED_SYNTHETIC_FULL_PATH_BENCHMARK_ONLY":
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    if basis.get("real_p5_labels_read_before_choice") is not False:
        raise AuthorityError("RESOURCE_POLICY_OUTCOME_DERIVED")
    digest = basis.get("benchmark_sha256")
    if not isinstance(digest, str) or len(digest) != 64 or any(
            c not in "0123456789abcdef" for c in digest):
        raise AuthorityError("RESOURCE_POLICY_BENCHMARK_HASH_INVALID")
    return value


def resource_policy_sha256(value: Any) -> str:
    validate_resource_policy(value)
    return sha256(canonical_json(value))


@dataclass(frozen=True)
class FrozenBindings:
    family_id: str
    run_id: str
    run_class: str
    evidence_domain: str
    prereg_sha256: str
    dataset_manifest_sha256: str
    revision_lineage_sha256: str
    universe_rule_sha256: str
    validation_contract_sha256: str
    cost_contract: str
    evaluator_sha256: str
    cutoff: str
    wave_id: str | None = None
    candidate_grammar_sha256: str | None = None
    candidate_list_sha256: str | None = None
    candidate_count: int | None = None
    enumerator_sha256: str | None = None
    evaluation_order_sha256: str | None = None
    executable_contract_sha256: str | None = None
    risc_rule: str | None = None
    resource_scope: dict[str, Any] | None = None

    def validate(self) -> "FrozenBindings":
        if self.run_class not in RUN_CLASSES:
            raise AuthorityError("unsupported run_class")
        for name, value in vars(self).items():
            if name.endswith("sha256") and value is not None:
                if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                    raise AuthorityError(f"invalid {name}")
        if self.wave_id is not None:
            required = (self.wave_id, self.candidate_grammar_sha256,
                        self.candidate_list_sha256, self.enumerator_sha256,
                        self.evaluation_order_sha256,
                        self.executable_contract_sha256, self.risc_rule,
                        self.resource_scope)
            if any(value is None for value in required) or self.candidate_count != 174:
                raise AuthorityError("Wave-1 bindings incomplete")
            validate_resource_policy(self.resource_scope)
        elif self.resource_scope is not None:
            raise AuthorityError("RESOURCE_POLICY_ONLY_ALLOWED_FOR_WAVE1")
        return self

    @property
    def digest(self) -> str:
        self.validate()
        return sha256(canonical_json(vars(self)))


@dataclass(frozen=True)
class DaemonContext:
    peer_uid: int
    session_id: str
    recorded_at: str
    ledger_sequence: int

    def validate(self) -> "DaemonContext":
        if type(self.peer_uid) is not int or self.peer_uid < 0:
            raise AuthorityError("invalid daemon peer uid")
        if not self.session_id or type(self.ledger_sequence) is not int:
            raise AuthorityError("daemon session/order missing")
        parse_utc(self.recorded_at)
        return self


@dataclass
class AuthorityProposal:
    proposal_id: str
    bindings: FrozenBindings
    producer_session_id: str
    expires_at: str
    state: str = "PROPOSED"
    events: list[dict[str, Any]] = field(default_factory=list)
    applied_grant_id: str | None = None


class AuthorityFSM:
    """Fail-closed FSM whose trust inputs come only from the daemon."""

    def __init__(self, owner_peer_uid: int,
                 daemon_context: Callable[[], DaemonContext]):
        self._owner_peer_uid = owner_peer_uid
        self._daemon_context = daemon_context

    def _ctx(self) -> DaemonContext:
        return self._daemon_context().validate()

    def _append(self, proposal: AuthorityProposal, target: str,
                details: dict[str, Any]) -> None:
        current_index = STATES.index(proposal.state)
        if current_index + 1 >= len(STATES) or STATES[current_index + 1] != target:
            raise AuthorityError(f"illegal transition {proposal.state}->{target}")
        ctx = self._ctx()
        if proposal.events and ctx.ledger_sequence <= proposal.events[-1]["ledger_sequence"]:
            raise AuthorityError("daemon ledger order is not append-only")
        proposal.events.append({
            "from": proposal.state, "to": target,
            "daemon_recorded_at": ctx.recorded_at,
            "ledger_sequence": ctx.ledger_sequence,
            "immutable_session_id": ctx.session_id,
            "peer_uid": ctx.peer_uid,
            "details": details,
        })
        proposal.state = target

    def preconditions_pass(self, proposal: AuthorityProposal,
                           observed_binding_digest: str) -> None:
        if observed_binding_digest != proposal.bindings.digest:
            raise BindingMismatch("precondition binding digest mismatch")
        self._append(proposal, "PRECONDITIONS_PASS",
                     {"binding_digest": observed_binding_digest})

    def human_owner_sign(self, proposal: AuthorityProposal) -> None:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("HUMAN_OWNER_SIGNED requires owner daemon credential")
        if ctx.session_id == proposal.producer_session_id:
            raise AuthorizationDenied("owner session must differ from producer session")
        self._append(proposal, "HUMAN_OWNER_SIGNED",
                     {"owner_peer_uid": ctx.peer_uid})

    def apply(self, proposal: AuthorityProposal) -> str:
        ctx = self._ctx()
        if parse_utc(ctx.recorded_at) >= parse_utc(proposal.expires_at):
            raise AuthorizationDenied("grant expired under daemon-authoritative time")
        grant_id = "grant-" + sha256(canonical_json({
            "proposal_id": proposal.proposal_id,
            "binding_digest": proposal.bindings.digest,
            "owner_session": ctx.session_id,
        }))[:32]
        self._append(proposal, "APPLIED", {"grant_id": grant_id})
        proposal.applied_grant_id = grant_id
        return grant_id


@dataclass
class Attempt:
    attempt_id: str
    logical_trial_id: str
    ordinal: int
    state: str = "RUNNING"


class TrialRegistry:
    """One logical wave per grant; infrastructure retries keep its identity."""

    def __init__(self) -> None:
        self._logical_by_grant: dict[str, tuple[str, str]] = {}
        self._attempts: dict[str, list[Attempt]] = {}

    def open_wave(self, grant_id: str, candidate_list_sha256: str) -> Attempt:
        existing = self._logical_by_grant.get(grant_id)
        if existing is None:
            logical = "logical-" + sha256(canonical_json(
                {"grant_id": grant_id, "candidate_list_sha256": candidate_list_sha256}))[:32]
            self._logical_by_grant[grant_id] = (logical, candidate_list_sha256)
            self._attempts[logical] = []
        else:
            logical, frozen_hash = existing
            if frozen_hash != candidate_list_sha256:
                raise BindingMismatch("new candidate list requires a new grant/wave")
        ordinal = len(self._attempts[logical]) + 1
        attempt = Attempt(f"{logical}-attempt-{ordinal:04d}", logical, ordinal)
        self._attempts[logical].append(attempt)
        return attempt

    def void_attempt(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can be voided")
        attempt.state = "ATTEMPT_VOID"

    def complete(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can complete")
        if any(a.state == "COMPLETED" for a in self._attempts[attempt.logical_trial_id]):
            raise AuthorityError("duplicate logical result")
        attempt.state = "COMPLETED"

    @property
    def logical_trial_count(self) -> int:
        return len(self._logical_by_grant)

